(()=>{
 const P=Planning,phases=['Discovery','Design','Development','Launch'];

 let view='overview',projectFilter='all',query='',zoom=36,editing=null,dragging=null;const closed=new Set();
 const main=$('main'),overview=[...main.children].filter(el=>el.tagName!=='FOOTER');
 const surface=document.createElement('section');surface.id='planning';surface.className='hidden';surface.innerHTML=`<div class="planning-title"><div><p class="eyebrow">PROJECT PLANNING</p><h1 id="planning-title"></h1><p id="planning-description" class="muted"></p></div><button class="primary" id="add-task">+ Add task</button></div><div class="planning-toolbar"><div class="plan-tabs" role="tablist" aria-label="Planning views"><button role="tab" data-switch="wbs">Work breakdown</button><button role="tab" data-switch="kanban">Kanban</button><button role="tab" data-switch="gantt">Gantt chart</button></div><div class="plan-filters"><label class="sr-only" for="plan-project">Filter by project</label><select id="plan-project"></select><label class="search">⌕ <input id="task-search" placeholder="Find a task…" aria-label="Find a task"></label></div></div><div id="plan-summary"></div><div id="plan-content"></div><p class="planning-help">Shared tasks across all planning views</p>`;main.insertBefore(surface,$('footer'));
 const editor=document.createElement('dialog');editor.id='task-editor';editor.setAttribute('aria-labelledby','task-editor-title');editor.innerHTML=`<form id="task-form"><div class="panel-heading"><h2 id="task-editor-title">New task</h2><button type="button" data-close-task class="icon-btn" aria-label="Close task editor">×</button></div><div class="task-fields"><label for="task-name">Task name</label><input id="task-name" name="name" required maxlength="120"><label for="task-description">Description / reproduction steps</label><textarea id="task-description" name="description" rows="4"></textarea><div class="field-grid"><div><label for="task-kind">Type</label><select id="task-kind" name="kind"><option>Task</option><option>Bug</option></select></div><div><label for="task-priority">Priority</label><select id="task-priority" name="priority"><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select></div><div><label for="task-project">Project</label><select id="task-project" name="projectId" required></select></div><div><label for="task-phase">Work package</label><select id="task-phase" name="phase">${phases.map(p=>`<option>${p}</option>`).join('')}</select></div><div><label for="task-status">Status</label><select id="task-status" name="status">${P.statuses.map(p=>`<option>${p}</option>`).join('')}</select></div><div><label for="task-assignee">Assignee</label><select id="task-assignee" name="assigneeId"><option value="">Unassigned</option></select></div><div><label for="task-start">Start date</label><input type="date" id="task-start" name="startDate" required min="2000-01-01" max="2100-12-31"></div><div><label for="task-end">End date</label><input type="date" id="task-end" name="endDate" required min="2000-01-01" max="2100-12-31"></div></div><section class="ticket-attachments"><h3>Images</h3><div id="ticket-images"></div><label for="task-image">Attach an image (PNG, JPEG or WebP · up to 25 MB)</label><input type="file" id="task-image" name="image" accept="image/png,image/jpeg,image/webp"><small>Uploaded when you save. Click a thumbnail to view the full image.</small></section><p id="task-error" role="alert"></p></div><div class="dialog-actions"><button type="button" class="secondary" data-close-task>Cancel</button><button class="primary" type="submit">Save task</button></div></form>`;document.body.append(editor);
 const initials=name=>name.split(' ').map(n=>n[0]).join('');
 const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
 const filtered=()=>issues.filter(t=>(projectFilter==='all'||t.projectId===projectFilter)&&(!query||(t.name+' '+ProjectAPI.ticketKey(t)+' '+t.id+' '+t.kind+' '+t.assignee).toLowerCase().includes(query)));
 const statusSelect=t=>`<select class="task-status ${P.colors[t.status]}" data-status="${t.id}" aria-label="Status for ${esc(t.name)}">${P.statuses.map(s=>`<option${s===t.status?' selected':''}>${s}</option>`).join('')}</select>`;
 const meter=tasks=>`<span class="rollup"><span class="progress-track"><i style="width:${P.progress(tasks)}%"></i></span>${P.progress(tasks)}%</span>`;
 function projectOptions(selected,all=false){return (all?'<option value="all">All projects</option>':'')+projects.map(p=>`<option value="${p.id}"${p.id===selected?' selected':''}>${esc(p.name)}</option>`).join('')}
 function show(next){window.dispatchEvent(new CustomEvent('planning:navigate',{detail:next}));view=next;overview.forEach(el=>el.classList.toggle('hidden',next!=='overview'));surface.classList.toggle('hidden',next==='overview');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',next==='overview'?b.dataset.view==='overview':b.dataset.plan===next));$('#crumb').textContent=next==='overview'?'Dashboard':{wbs:'Work breakdown',kanban:'Kanban board',gantt:'Gantt chart'}[next];$('#search').closest('.search').classList.toggle('hidden',next!=='overview');if(next!=='overview')draw();if(innerWidth<980)document.body.classList.remove('collapsed');window.scrollTo({top:0,behavior:'instant'})}
 function draw(){if(view==='overview')return;$('#planning-title').textContent={wbs:'Work breakdown structure',kanban:'Kanban board',gantt:'Gantt chart'}[view];$('#planning-description').textContent={wbs:'Organize deliverables into projects, work packages, and tasks.',kanban:'Move work forward, one task at a time.',gantt:'Plan dates and see how work fits together.'}[view];$('#plan-project').innerHTML=projectOptions(projectFilter,true);$('#plan-project').value=projectFilter;document.querySelectorAll('[data-switch]').forEach(b=>{b.classList.toggle('active',b.dataset.switch===view);b.setAttribute('aria-selected',b.dataset.switch===view)});let tasks=filtered();$('#plan-summary').innerHTML=`<span><b>${tasks.length}</b> tasks</span><span><b>${tasks.filter(t=>t.status==='In Progress').length}</b> in progress</span><span><b>${tasks.filter(t=>t.status==='Done').length}</b> completed</span>${meter(tasks)}`;if(view==='wbs')drawWbs(tasks);if(view==='kanban')drawKanban(tasks);if(view==='gantt')drawGantt(tasks)}
 function drawWbs(tasks){let html='<div class="panel wbs"><div class="wbs-top"><span>DELIVERABLE / TASK</span><button class="secondary" id="expand-wbs">Expand all</button><button class="secondary" id="collapse-wbs">Collapse all</button></div>';projects.filter(p=>projectFilter==='all'||p.id===projectFilter).forEach(p=>{let pTasks=tasks.filter(t=>t.projectId===p.id);if(query&&!pTasks.length)return;let pn=projects.indexOf(p)+1,pClosed=closed.has(p.id);html+=`<div class="wbs-project"><div class="wbs-row group"><button class="tree-toggle" data-toggle="${p.id}" aria-expanded="${!pClosed}" aria-label="${pClosed?'Expand':'Collapse'} ${esc(p.name)}">${pClosed?'▸':'▾'}</button><span class="wbs-number">${pn}</span><strong>${esc(p.name)}</strong><span class="count">${pTasks.length} tasks</span>${meter(pTasks)}</div>`;if(!pClosed)phases.forEach((phase,pi)=>{let key=p.id+'-'+pi,children=pTasks.filter(t=>t.phase===phase),isClosed=closed.has(key);if(query&&!children.length)return;html+=`<div class="wbs-row phase"><button class="tree-toggle" data-toggle="${key}" aria-expanded="${!isClosed}" aria-label="${isClosed?'Expand':'Collapse'} ${esc(p.name+' '+phase)}">${isClosed?'▸':'▾'}</button><span class="wbs-number">${pn}.${pi+1}</span><strong>${phase}</strong><span class="count">${children.length}</span>${meter(children)}<button class="text-btn" data-package="${p.id}" data-phase="${phase}" aria-label="Add task to ${esc(p.name+' '+phase)}">+ Add task</button></div>`;if(!isClosed)children.forEach((t,ti)=>{html+=`<div class="wbs-row task"><span class="wbs-number">${pn}.${pi+1}.${ti+1}</span><button class="task-title" data-edit="${t.id}">${esc(t.name)}<small>${esc(ProjectAPI.ticketKey(t))} · ${esc(t.kind)} · ${esc(t.assignee)} · ${dateLabel(t.startDate)} – ${dateLabel(t.endDate)}</small></button>${statusSelect(t)}</div>`})});html+='</div>'});html+='</div>';$('#plan-content').innerHTML=html+(query&&!tasks.length?'<p class="empty">No tasks match your search.</p>':'')}
 function drawKanban(tasks){$('#plan-content').innerHTML=`<p class="board-hint">Drag cards between columns, or use a card’s status menu.</p><div class="kanban-board">${P.statuses.map(s=>{let column=tasks.filter(t=>t.status===s);return `<section class="kanban-column" data-drop="${s}" aria-label="${s} column"><div class="column-title"><span><i class="dot ${P.colors[s]}"></i>${s}</span><span class="count">${column.length}</span></div><div class="column-cards">${column.map(t=>`<article class="kanban-card" draggable="true" data-drag="${t.id}"><span class="card-id">${esc(ProjectAPI.ticketKey(t))} · ${esc(t.kind)} · ${esc(t.phase)}</span><button class="task-title" data-edit="${t.id}">${esc(t.name)}</button><p class="card-project">${esc(projects.find(p=>p.id===t.projectId)?.name||'')}</p><div class="card-meta">${window.Workspace?Workspace.avatarByName(t.assignee):`<span class="avatar" title="${esc(t.assignee)}">${initials(t.assignee)}</span>`}<time>${dateLabel(t.endDate)}</time></div>${statusSelect(t)}</article>`).join('')||'<div class="empty-column">No tasks here</div>'}</div><button class="add-column-task" data-new-status="${s}">+ Add task</button></section>`}).join('')}</div>`}
 function drawGantt(tasks){if(!tasks.length){$('#plan-content').innerHTML='<div class="panel empty">No tasks match your filters. Add a task or adjust your search.</div>';return;}let b=P.bounds(tasks),width=b.days*zoom;let ticks='';for(let d=0;d<b.days;d++){let date=P.iso(b.start+d),weekday=new Date(date+'T12:00:00Z').getUTCDay();ticks+=`<div class="gantt-day ${weekday===0||weekday===6?'weekend':''}" style="width:${zoom}px">${zoom>=30?`<small>${dateLabel(date).split(' ')[0]}</small>${Number(date.slice(-2))}`:d%7===0?dateLabel(date):''}</div>`}let today=P.day(new Date().toISOString().slice(0,10)),todayMarker=today>=b.start&&today<=b.end?`<span class="today-marker" style="left:${(today-b.start)*zoom+zoom/2}px" title="Today"></span>`:'';$('#plan-content').innerHTML=`<div class="gantt-tools"><span>${dateLabel(P.iso(b.start))}, ${P.iso(b.start).slice(0,4)} – ${dateLabel(P.iso(b.end))}, ${P.iso(b.end).slice(0,4)}</span><div><label for="gantt-zoom">Scale</label> <select id="gantt-zoom"><option value="36"${zoom===36?' selected':''}>Day</option><option value="14"${zoom===14?' selected':''}>Week</option></select></div></div><div class="panel gantt-scroll" tabindex="0" aria-label="Gantt chart, scroll horizontally for more dates"><div class="gantt-table" style="width:${width+280}px;--day-width:${zoom}px"><div class="gantt-row gantt-header"><div class="gantt-label">TASK / SCHEDULE</div><div class="gantt-track" style="width:${width}px">${ticks}</div></div>${tasks.map(t=>`<div class="gantt-row"><button class="gantt-label" data-edit="${t.id}"><strong>${esc(t.name)}</strong><small>${esc(ProjectAPI.ticketKey(t))} · ${esc(t.kind)} · ${dateLabel(t.startDate)} – ${dateLabel(t.endDate)}</small></button><div class="gantt-track grid-track" style="width:${width}px">${todayMarker}<button class="gantt-bar ${P.colors[t.status]}" data-edit="${t.id}" style="left:${(P.day(t.startDate)-b.start)*zoom+2}px;width:${(P.day(t.endDate)-P.day(t.startDate)+1)*zoom-4}px" aria-label="Edit ${esc(t.name)}, ${t.startDate} to ${t.endDate}, ${t.status}" title="${esc(t.name)} · ${t.startDate} to ${t.endDate} · ${t.status}">${taskAvatar(t)}<span class="gantt-task-name">${esc(t.name)}</span></button></div></div>`).join('')}</div></div><div class="gantt-legend">${P.statuses.map(s=>`<span><i class="dot ${P.colors[s]}"></i>${s}</span>`).join('')}<span>Click a task to edit dates</span></div>`}
 function openTask(id,defaults={}){if(!projects.length){toast('Create a project first.');return;}editing=id||null;let task=issues.find(t=>t.id===id)||{name:'',projectId:projectFilter==='all'?projects[0].id:projectFilter,phase:'Development',status:'Todo',kind:'Task',priority:'Medium',description:'',assigneeId:null,assignee:'Unassigned',startDate:new Date().toISOString().slice(0,10),endDate:new Date().toISOString().slice(0,10),...defaults};if(window.Workspace){$('#task-assignee').innerHTML=Workspace.memberIdOptions(task.assigneeId);}
 $('#task-editor-title').textContent=id?'Edit task · '+ProjectAPI.ticketKey(task):'New task';$('#task-project').innerHTML=projectOptions(task.projectId);$('#task-project').disabled=!!id;setTicketTypes(task.kind);for(let name of ['name','description','priority','phase','status','assigneeId','startDate','endDate'])$('#task-form').elements[name].value=task[name]??(name==='priority'?'Medium':name==='kind'?'Task':'');$('#task-error').textContent='';$('#task-image').value='';renderTicketImages();editor.showModal();$('#task-name').focus()}
 function setTicketTypes(preferred){const types=projects.find(p=>p.id===$('#task-project').value)?.ticketTypes||['Task','Bug','Subtask'];$('#task-kind').innerHTML=types.map(type=>`<option>${esc(type)}</option>`).join('');$('#task-kind').value=types.includes(preferred)?preferred:types[0]}
 $('#task-project').onchange=()=>setTicketTypes($('#task-kind').value);
 function renderTicketImages(){const images=window.Workspace?.ticketImages(editing)||[];$('#ticket-images').innerHTML=images.length?images.map(d=>`<button type="button" class="ticket-image" data-preview-image="${d.id}" aria-label="Preview ${esc(d.name)}"><img src="/api/documents/${d.id}/preview" alt="${esc(d.name)}" loading="lazy"><span>${esc(d.name)}</span></button>`).join(''):'<p class="muted">No images attached yet.</p>';}
 const viewer=document.createElement('dialog');viewer.className='ticket-image-viewer';viewer.setAttribute('aria-label','Image preview');document.body.append(viewer);
 editor.addEventListener('click',e=>{const button=e.target.closest('[data-preview-image]');if(!button)return;const doc=Workspace.ticketImages(editing).find(d=>d.id===button.dataset.previewImage);if(!doc)return;viewer.innerHTML=`<div class="panel-heading"><h2>${esc(doc.name)}</h2><button type="button" class="icon-btn" aria-label="Close image preview">×</button></div><img src="/api/documents/${doc.id}/preview" alt="${esc(doc.name)}"><a class="secondary" href="/api/documents/${doc.id}/download">Download original</a>`;viewer.querySelector('button').onclick=()=>viewer.close();viewer.showModal()});
 async function changed(message){issues.forEach(t=>{t.color=P.colors[t.status];t.assigneeInitials=ProjectAPI.assigneeInitials(t.assignee)});await window.Workspace?.persist();render();draw();window.dispatchEvent(new Event('workspace:changed'));toast(message)}
 async function setStatus(id,status){let t=issues.find(t=>t.id===id);if(!t||!P.statuses.includes(status)||t.status===status)return;const old=t.status;t.status=status;try{await changed(t.id+' moved to '+status)}catch(error){t.status=old;render();draw();toast(error.message)}}
 function syncOverview(){
 $('#stats').innerHTML=[['Total Projects',projects.length,'Projects in this workspace'],['Total Tasks',issues.length,'Shared planning tasks'],['In Progress',issues.filter(t=>t.status==='In Progress').length,'Tasks underway'],['Completed',issues.filter(t=>t.status==='Done').length,'Tasks delivered']].map(([label,value,desc])=>`<article class="stat"><div class="stat-label">${label}</div><strong>${value}</strong><small>${desc}</small></article>`).join('');
 $('#nav-project-count').textContent=projects.length;$('#nav-issue-count').textContent=issues.length;
 let counts=P.statuses.map(s=>issues.filter(t=>t.status===s).length),palette=['#dadce2','#9ecddf','#e1c775','#b9a2d8','#98b5a4'],offset=0;
 let stops=counts.map((n,i)=>{let start=offset;offset+=n/(issues.length||1)*100;return `${palette[i]} ${start}% ${offset}%`});
 $('#issue-status-donut').style.background=issues.length?`conic-gradient(${stops.join(',')})`:'#e9e9ef';$('#issue-status-total').innerHTML=`${issues.length}<small>Total issues</small>`;
 $('#issue-status-legend').innerHTML=P.statuses.map((s,i)=>`<p><i class="dot ${P.colors[s]}"></i>${s}<b>${counts[i]}</b></p>`).join('');$('#issue-status-count').textContent=issues.length+(issues.length===1?' issue':' issues');
 }
 const baseRender=render;render=function(){baseRender();syncOverview();if(view!=='overview')draw()};
 const originalCreate=openCreate;openCreate=function(t){if(t==='issue')openTask();else originalCreate(t)};
 // The overview's issue map uses the same editable task records.
 document.addEventListener('click',e=>{let issue=e.target.closest('[data-issue]');if(issue&&!e.target.closest('[data-member-profile]')){e.stopImmediatePropagation();openTask(issues[Number(issue.dataset.issue)].id)}},true);
 document.querySelectorAll('nav [data-view]').forEach(b=>{let original=b.onclick;b.onclick=()=>{show('overview');original()}});
 document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>show(b.dataset.plan));
 surface.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.switch)show(b.dataset.switch);if(b.dataset.edit)openTask(b.dataset.edit);if(b.dataset.toggle){let key=b.dataset.toggle;closed.has(key)?closed.delete(key):closed.add(key);draw()}if(b.dataset.package)openTask(null,{projectId:b.dataset.package,phase:b.dataset.phase});if(b.dataset.newStatus)openTask(null,{status:b.dataset.newStatus});if(b.id==='add-task')openTask();if(b.id==='expand-wbs'){closed.clear();draw()}if(b.id==='collapse-wbs'){projects.forEach(p=>closed.add(p.id));draw()}});
 surface.addEventListener('change',e=>{if(e.target.dataset.status)setStatus(e.target.dataset.status,e.target.value);if(e.target.id==='plan-project'){projectFilter=e.target.value;draw()}if(e.target.id==='gantt-zoom'){zoom=Number(e.target.value);draw()}});
 $('#task-search').oninput=e=>{query=e.target.value.toLowerCase().trim();draw()};
 surface.addEventListener('dragstart',e=>{let card=e.target.closest('[data-drag]');if(!card)return;dragging=card.dataset.drag;e.dataTransfer.setData('text/plain',dragging);e.dataTransfer.effectAllowed='move';card.classList.add('dragging')});
 surface.addEventListener('dragover',e=>{let column=e.target.closest('[data-drop]');if(!column||!dragging)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));column.classList.add('drop-target')});
 surface.addEventListener('drop',e=>{let column=e.target.closest('[data-drop]');if(!column||!dragging)return;e.preventDefault();setStatus(dragging,column.dataset.drop);dragging=null});surface.addEventListener('dragend',()=>{dragging=null;document.querySelectorAll('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging'))});
 editor.querySelectorAll('[data-close-task]').forEach(b=>b.onclick=()=>editor.close());
 $('#task-form').onsubmit=async e=>{
  e.preventDefault();const button=e.target.querySelector('[type=submit]');if(button.disabled)return;
  const form=new FormData(e.target),file=form.get('image');form.delete('image');if(editing)form.set('projectId',issues.find(t=>t.id===editing).projectId);let values=Object.fromEntries(form);values.name=values.name.trim();values.assigneeId=values.assigneeId||null;values.assignee=Workspace.memberName(values.assigneeId);
  let error=P.validate(values);if(!error&&file?.size&&(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>26214400))error='Choose a PNG, JPEG or WebP image up to 25 MB.';
  if(error){$('#task-error').textContent=error;return;}
  const before=structuredClone(issues);let existing=issues.find(t=>t.id===editing),saved=false;button.disabled=true;button.textContent='Saving…';
  try{if(existing)Object.assign(existing,values);else{existing={...values,id:crypto.randomUUID(),color:P.colors[values.status]};issues.push(existing)}await changed('Ticket saved');saved=true;editing=existing.id;
    if(file?.size){await Workspace.attachTicketImage(existing,file);$('#task-image').value='';renderTicketImages();toast('Ticket and image saved')}
    editor.close();
  }catch(error){if(!saved)issues=before;$('#task-error').textContent=(saved?'Ticket saved, but the image upload failed. Retry saving to upload it. ':'')+error.message;render();draw();renderTicketImages()}finally{button.disabled=false;button.textContent='Save task'}
 };
 // Calendar ranges keep the axis, task bars and today marker aligned.
 let timelineRange='Week';
 renderTimeline=function(){
  const today=new Date().toLocaleDateString('en-CA'),period=P.timelineWindow(timelineRange,today);
  const tasks=issues.filter(t=>P.dateValid(t.startDate)&&P.dateValid(t.endDate)).sort((a,b)=>a.startDate.localeCompare(b.startDate)||a.id.localeCompare(b.id));
  const start=Math.min(period.start,...tasks.map(t=>P.day(t.startDate))),end=Math.max(period.end,...tasks.map(t=>P.day(t.endDate))),days=end-start+1;
  const plotWidth=Math.max(540,days*({Week:48,Month:24,Quarter:12}[timelineRange])),todayPosition=(P.day(today)-start+.5)/days*100;
  $('#timeline').innerHTML=tasks.length?`<div class="map-scroll" tabindex="0" aria-label="Issue timeline, scroll for more dates and tasks"><div class="map-canvas" style="width:${plotWidth+260}px"><div class="axis"><span>${dateLabel(P.iso(start))}</span><span>${dateLabel(P.iso(end))}</span></div><div class="timeline-rows">${tasks.map(t=>{const left=(P.day(t.startDate)-start)/days*100,width=(P.day(t.endDate)-P.day(t.startDate)+1)/days*100;return `<div class="issue-row"><div class="issue-name">${taskAvatar(t)}<button class="map-task-label" data-issue="${issues.indexOf(t)}"><strong>${esc(ProjectAPI.ticketKey(t))} · ${esc(t.name)}</strong><small>${esc(t.status)} · ${dateLabel(t.startDate)} – ${dateLabel(t.endDate)}</small></button></div><div class="track"><button class="bar ${P.colors[t.status]}" style="left:${left}%;width:${width}%" data-issue="${issues.indexOf(t)}" title="${esc(ProjectAPI.ticketKey(t))} · ${esc(t.name)} · ${dateLabel(t.startDate)} – ${dateLabel(t.endDate)}" aria-label="Open ${esc(ProjectAPI.ticketKey(t))}: ${esc(t.name)}"><span class="timeline-task-name">${esc(t.name)}</span></button></div></div>`}).join('')}<div class="timeline-marker-area"><span class="timeline-today" style="left:${todayPosition}%"><b>Today</b></span></div></div></div></div><p class="timeline-more">${tasks.length} tasks · ${timelineRange} scale · Scroll to explore dates. Names and avatars stay visible.</p>`:'<p class="timeline-empty">No scheduled tasks yet.</p>';
  $('#range').querySelectorAll('[data-timeline-range]').forEach(button=>{const selected=button.dataset.timelineRange===timelineRange;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected))});
 };
 window.PlanningUI={show,refresh:draw,setProject(id){projectFilter=id;draw()},openTask};
 $('#range').innerHTML=['Week','Month','Quarter'].map(range=>`<button data-timeline-range="${range}">${range}</button>`).join('')+'<button id="full-gantt">Open Gantt</button>';$('#range').onclick=e=>{if(e.target.closest('#full-gantt'))show('gantt');else if(e.target.dataset.timelineRange){timelineRange=e.target.dataset.timelineRange;renderTimeline()}};issues.forEach(t=>t.color=P.colors[t.status]);render();
})();
